package com.hs.jxc.md.controller;
import com.hs.jxc.common.api.*;
import com.hs.jxc.common.context.*;
import com.hs.jxc.common.db.DbRows;
import com.hs.jxc.common.audit.AuditWriter;
import com.hs.jxc.common.idempotency.IdempotencyExecutor;
import com.hs.jxc.md.api.FxApi;
import com.hs.jxc.sys.service.AuthorizationService;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/md")
public class ProductFxController {
 private final com.hs.jxc.md.api.MasterProductMaintenanceApi maintenance;private final JdbcTemplate jdbc;private final AuthorizationService auth;private final IdempotencyExecutor idem;private final AuditWriter audit;private final FxApi fx;private final TransactionTemplate tx;
 public ProductFxController(JdbcTemplate jdbc,AuthorizationService auth,IdempotencyExecutor idem,AuditWriter audit,FxApi fx,PlatformTransactionManager tm,com.hs.jxc.md.api.MasterProductMaintenanceApi maintenance){this.maintenance=maintenance;this.jdbc=jdbc;this.auth=auth;this.idem=idem;this.audit=audit;this.fx=fx;this.tx=new TransactionTemplate(tm);}
 @GetMapping({"/products","/categories","/country-skus","/exchange-rates"}) public ApiEnvelope list(jakarta.servlet.http.HttpServletRequest request,@RequestParam Map<String,String> q){var c=RequestContextHolder.require();String kind=request.getRequestURI().substring(request.getRequestURI().lastIndexOf('/')+1);return ApiEnvelope.ok(tx.execute(s->{var a=auth.authorize(c);a.require(kind.equals("exchange-rates")?"md:rate:edit":"md:product:view",kind.equals("exchange-rates")?"md:rate:confirm":"md:product:edit");int page=number(q.get("page"),1,1000000),size=number(q.get("size"),20,200);List<Object> args=new ArrayList<>();String table=switch(kind){case "categories"->"md_category";case "exchange-rates"->"md_exchange_rate";default->"md_product";};String where=kind.equals("exchange-rates")?"country_id=?":"TRUE";if(kind.equals("exchange-rates"))args.add(a.requireCountry());if(q.get("keyword")!=null&&!q.get("keyword").isBlank()){where+=" AND "+(kind.equals("categories")?"(code ILIKE ? OR name ILIKE ?)":kind.equals("exchange-rates")?"(from_ccy ILIKE ? OR to_ccy ILIKE ?)":"(product_code ILIKE ? OR name ILIKE ?)");args.add("%"+q.get("keyword")+"%");args.add("%"+q.get("keyword")+"%");}if(q.get("status")!=null){where+=" AND status=?";args.add(q.get("status"));}if(kind.equals("country-skus")&&q.get("enabled")!=null){where+=" AND "+(Boolean.parseBoolean(q.get("enabled"))?"EXISTS":"NOT EXISTS")+" (SELECT 1 FROM md_country_sku s WHERE s.country_id=? AND s.product_id=md_product.id AND s.status='ENABLED')";args.add(a.requireCountry());}long total=jdbc.queryForObject("SELECT count(*) FROM "+table+" WHERE "+where,Long.class,args.toArray());args.add(size);args.add((page-1)*size);var rows=jdbc.queryForList("SELECT * FROM "+table+" WHERE "+where+" ORDER BY id LIMIT ? OFFSET ?",args.toArray()).stream().map(DbRows::camel).toList();if(table.equals("md_product"))for(var row:rows){enrichProduct(row);if(kind.equals("country-skus")){var sku=jdbc.queryForList("SELECT * FROM md_country_sku WHERE country_id=? AND product_id=?",a.requireCountry(),row.get("id"));row.put("productId",row.get("id"));row.put("productStatus",row.get("status"));row.put("enabled",!sku.isEmpty()&&"ENABLED".equals(sku.getFirst().get("status")));row.put("version",sku.isEmpty()?0:sku.getFirst().get("version"));row.put("localName",sku.isEmpty()?"":sku.getFirst().get("local_name"));row.put("taxCategory",sku.isEmpty()?"":sku.getFirst().get("tax_category"));row.put("label",row.get("productCode")+" "+row.get("name"));}}return Map.of("records",rows,"total",total,"page",page,"size",size);}),c.traceId());}
 @GetMapping("/products/{id}") public ApiEnvelope product(@PathVariable long id){var c=RequestContextHolder.require();return ApiEnvelope.ok(tx.execute(s->{var a=auth.authorize(c);a.require("md:product:view");var row=DbRows.camel(global("md_product",Inputs.id(id),false));enrichProduct(row);return row;}),c.traceId());}
 @PostMapping("/products") public ApiEnvelope productCreate(@RequestBody Map<String,Object> b,@RequestHeader(value="Idempotency-Key",required=false) String key){return productWrite(null,b,key);}
 @PutMapping("/products/{id}") public ApiEnvelope productUpdate(@PathVariable long id,@RequestBody Map<String,Object> b,@RequestHeader(value="Idempotency-Key",required=false) String key){return productWrite(Inputs.id(id),b,key);}
 private ApiEnvelope productWrite(Long id,Map<String,Object> b,String key){var c=RequestContextHolder.require();return ApiEnvelope.ok(saveProduct(c,id,b,key),c.traceId());}
 public Map<String,Object> saveProduct(RequestContext c,Long id,Map<String,Object> b,String key){return maintenance.saveProduct(c,id,b,key);}
 @PostMapping("/categories") public ApiEnvelope category(@RequestBody Map<String,Object> b,@RequestHeader(value="Idempotency-Key",required=false) String key){var c=RequestContextHolder.require();return ApiEnvelope.ok(tx.execute(s->{var a=auth.authorizePolicyWrite(c,true);a.require("md:product:edit");if(!a.platformAdmin())throw new ApiException(403,"SYS_FORBIDDEN","全局分类维护需要平台级授权");return idem.execute(c,"POST","/api/v1/md/categories",key,b,null,()->{long id=jdbc.queryForObject("INSERT INTO md_category(code,name,parent_id,level) VALUES(?,?,?,?) RETURNING id",Long.class,Inputs.required(b,"code"),Inputs.required(b,"name"),b.get("parentId")==null?null:Inputs.id(b.get("parentId")),MasterMaintenanceController.categoryLevel(jdbc,b.get("parentId")==null?null:Inputs.id(b.get("parentId")),null));var result=DbRows.camel(global("md_category",id,false));audit.append(c,"创建商品分类","MD_CATEGORY",id,null,result);return result;},r->{});}),c.traceId());}
 @PutMapping("/country-skus/{productId}") public ApiEnvelope sku(@PathVariable long productId,@RequestBody Map<String,Object> b,@RequestHeader(value="Idempotency-Key",required=false) String key){var c=RequestContextHolder.require();return ApiEnvelope.ok(maintenance.saveSku(c,productId,b,key),c.traceId());}
 @GetMapping("/exchange-rates/resolve") public ApiEnvelope resolve(@RequestParam String from,@RequestParam String to,@RequestParam String date,@RequestParam(defaultValue="ALL") String scope){var c=RequestContextHolder.require();return ApiEnvelope.ok(tx.execute(s->{var a=auth.authorize(c);var rate=fx.resolve(a.requireCountry(),from,to,LocalDate.parse(date),scope);Map<String,Object> result=new LinkedHashMap<>();result.put("rate",rate);if(rate==null)result.put("reason","待补已确认汇率");return result;}),c.traceId());}
 @GetMapping("/exchange-rates/{id}/versions") public ApiEnvelope versions(@PathVariable long id){var c=RequestContextHolder.require();return ApiEnvelope.ok(tx.execute(s->{var a=auth.authorize(c);a.require("md:rate:edit","md:rate:confirm");var old=rate(a.requireCountry(),Inputs.id(id),false);return jdbc.queryForList("SELECT * FROM md_exchange_rate WHERE country_id=? AND from_ccy=? AND to_ccy=? AND rate_date=? AND scope=? ORDER BY version_no DESC",a.requireCountry(),old.get("from_ccy"),old.get("to_ccy"),old.get("rate_date"),old.get("scope")).stream().map(DbRows::camel).toList();}),c.traceId());}
 @PostMapping("/exchange-rates") public ApiEnvelope rateCreate(@RequestBody Map<String,Object> b,@RequestHeader(value="Idempotency-Key",required=false) String key){return rateWrite(null,false,b,key);}
 @PutMapping("/exchange-rates/{id}") public ApiEnvelope rateUpdate(@PathVariable long id,@RequestBody Map<String,Object> b,@RequestHeader(value="Idempotency-Key",required=false) String key){return rateWrite(Inputs.id(id),false,b,key);}
 @PostMapping("/exchange-rates/{id}/confirm") public ApiEnvelope confirm(@PathVariable long id,@RequestBody(required=false) Map<String,Object> b,@RequestHeader(value="Idempotency-Key",required=false) String key){return rateWrite(Inputs.id(id),true,b==null?Map.of():b,key);}
 private ApiEnvelope rateWrite(Long id,boolean confirm,Map<String,Object> b,String key){var c=RequestContextHolder.require();return ApiEnvelope.ok(tx.execute(s->{var a=auth.authorize(c);a.require(confirm?"md:rate:confirm":"md:rate:edit");return idem.execute(c,id==null||confirm?"POST":"PUT","/api/v1/md/exchange-rates"+(id==null?"":"/"+id)+(confirm?"/confirm":""),key,b,null,()->{Map<String,Object> old=id==null?null:rate(a.requireCountry(),id,false);String from=old==null?Inputs.required(b,"fromCcy"):String.valueOf(old.get("from_ccy")),to=old==null?Inputs.required(b,"toCcy"):String.valueOf(old.get("to_ccy")),scope=old==null?Inputs.required(b,"scope"):String.valueOf(old.get("scope"));LocalDate date=old==null?LocalDate.parse(Inputs.required(b,"rateDate")):((java.sql.Date)old.get("rate_date")).toLocalDate();if(!from.matches("[A-Z]{3}")||!to.matches("[A-Z]{3}")||from.equals(to)||!Set.of("PURCHASE_COST","SETTLEMENT","REPORT","ALL").contains(scope))throw Inputs.bad("汇率币种或适用范围不合法");jdbc.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,a.requireCountry()+":"+from+":"+to+":"+date+":"+scope);if(id!=null){old=rate(a.requireCountry(),id,true);if(b.containsKey("version")&&Inputs.version(b)!=n(old,"version"))throw Inputs.conflict();}long actual;if(confirm){if(!"DRAFT".equals(old.get("status")))throw new ApiException(409,"SYS_STATE_INVALID","只有草稿汇率可以确认");jdbc.update("UPDATE md_exchange_rate SET status='RETIRED',version=version+1 WHERE country_id=? AND from_ccy=? AND to_ccy=? AND rate_date=? AND scope=? AND status='CONFIRMED'",a.requireCountry(),from,to,date,scope);jdbc.update("UPDATE md_exchange_rate SET status='CONFIRMED',confirmed_by=?,confirmed_at=clock_timestamp(),version=version+1 WHERE country_id=? AND id=?",c.userId(),a.requireCountry(),id);actual=id;}else{BigDecimal value=Inputs.decimal(b.get("rate"),8,new BigDecimal("1000000"));if(value.signum()<=0)throw Inputs.bad("汇率必须大于0");if(old!=null&&"DRAFT".equals(old.get("status"))){jdbc.update("UPDATE md_exchange_rate SET rate=?,version=version+1 WHERE country_id=? AND id=?",value,a.requireCountry(),id);actual=id;}else{if(old!=null&&"RETIRED".equals(old.get("status")))throw new ApiException(409,"SYS_STATE_INVALID","被替代的汇率不能修改");int version=jdbc.queryForObject("SELECT coalesce(max(version_no),0)+1 FROM md_exchange_rate WHERE country_id=? AND from_ccy=? AND to_ccy=? AND rate_date=? AND scope=?",Integer.class,a.requireCountry(),from,to,date,scope);actual=jdbc.queryForObject("INSERT INTO md_exchange_rate(country_id,from_ccy,to_ccy,rate_date,scope,rate,version_no,status) VALUES(?,?,?,?,?,?,?,'DRAFT') RETURNING id",Long.class,a.requireCountry(),from,to,date,scope,value,version);}}var result=DbRows.camel(rate(a.requireCountry(),actual,false));audit.append(c,confirm?"确认汇率":"维护汇率版本","MD_EXCHANGE_RATE",actual,old,result);return result;},r->{if(((Number)r.get("countryId")).longValue()!=a.requireCountry())throw ApiException.notFound();});}),c.traceId());}
 private Map<String,Object> rate(long country,long id,boolean lock){var rows=jdbc.queryForList("SELECT * FROM md_exchange_rate WHERE country_id=? AND id=?"+(lock?" FOR UPDATE":""),country,id);if(rows.isEmpty())throw ApiException.notFound();return rows.getFirst();}
 private Map<String,Object> global(String table,long id,boolean lock){var rows=jdbc.queryForList("SELECT * FROM "+table+" WHERE id=?"+(lock?" FOR UPDATE":""),id);if(rows.isEmpty())throw ApiException.notFound();return rows.getFirst();}
 private void enrichProduct(Map<String,Object> row){maintenance.enrichProduct(row);}
 private static long n(Map<String,Object> m,String k){return ((Number)m.get(k)).longValue();}
 private static BigDecimal decimal(Object v,int scale){return Inputs.decimal(v,scale,new BigDecimal("9999999999"));}
 private static int number(String raw,int fallback,int max){if(raw==null)return fallback;try{int n=Integer.parseInt(raw);if(n<1||n>max)throw Inputs.bad("分页参数不合法");return n;}catch(NumberFormatException e){throw Inputs.bad("分页参数不合法");}}
}
